mapper.select:
SELECT DATE_FORMAT(r.pay_time, #{dateFormat}) AS label, COALESCE(SUM(CASE WHEN r.direction = 'RECEIVE' THEN r.amount ELSE 0 END), 0) AS receive_amount, COALESCE(SUM(CASE WHEN r.direction != 'RECEIVE' THEN r.amount ELSE 0 END), 0) AS give_amount FROM gift_record_info_t r WHERE r.is_delete = 0 AND r.pay_time IS NOT NULL
AND r.direction = #{direction}
GROUP BY DATE_FORMAT(r.pay_time, #{dateFormat}) ORDER BY label
